package cli

import (
	"github.com/entireio/cli/internal/entireclient/contexts"
	"github.com/spf13/cobra"
)

// contextFlagValue applies --context to the process-wide selection as pflag
// parses it.
//
// Binding through a pflag.Value rather than a PersistentPreRun is deliberate:
// Set() runs during flag parsing — before any PreRun, before RunE, and before
// anything resolves a token — so there is no ordering to get wrong.
//
// That ordering is the whole reason, and it is worth being clear that it is now
// the only one. This used to also argue that a root PersistentPreRun would be
// shadowed by the subtrees that define their own (agent_group.go, the per-agent
// hooks commands), because cobra runs only the closest hook in the chain by
// default. It no longer does: root.go sets cobra.EnableTraverseRunHooks, so
// every ancestor's hook runs, root first. A pre-run would therefore work today
// — it would just resolve the identity later than flag parsing does, for no
// gain.
type contextFlagValue struct{ name string }

func (v *contextFlagValue) String() string { return v.name }
func (v *contextFlagValue) Type() string   { return "string" }

func (v *contextFlagValue) Set(name string) error {
	v.name = name
	contexts.SetFlagOverride(name)
	return nil
}

// addContextFlag registers --context as a persistent flag on the root command,
// so every subcommand that authenticates inherits it without per-command
// plumbing.
//
// It is global rather than per-command because it selects an identity, and every
// path that resolves one honours it (git, control plane, data API, cell routing,
// status, logout). Registering it only on the commands we think authenticate
// today is how it would drift out of sync: a new authenticating command would
// silently ignore it. The cost is that it also parses on commands with no
// identity to select, like `version` — harmless, and the same tradeoff kubectl
// makes with its own global --context.
func addContextFlag(cmd *cobra.Command) {
	// The back-quoted word is pflag's value placeholder, so this renders as
	// `--context name`. Any other back-quoted span here (e.g. around a command to
	// run) would be silently hijacked as the placeholder instead.
	cmd.PersistentFlags().Var(&contextFlagValue{}, "context",
		"Act as this saved login `name` for this command only, instead of the active context (entire auth contexts lists them)")
	if err := cmd.RegisterFlagCompletionFunc("context", completeContextFlag); err != nil {
		panic("register --context completion: " + err.Error())
	}
}

// completeContextFlag completes saved context names for --context. It reuses the
// same listing `auth use` completes against, so both offer the same names with
// the same descriptions.
func completeContextFlag(cmd *cobra.Command, _ []string, toComplete string) ([]string, cobra.ShellCompDirective) {
	// completeContextNames takes the positional args of `auth use <context>`; pass
	// none so it treats this as completing the first (and only) value.
	return completeContextNames(cmd, nil, toComplete)
}

package contexts

import (
	"fmt"
	"os"
	"strings"
	"sync/atomic"
)

// EnvContextVar selects the acting login context for one process — the
// environment counterpart to `--context`.
//
// Both exist because they reach different entry points. A flag can't reach git
// operations at all: git invokes the `git-remote-entire` helper itself, so
// `ENTIRE_CONTEXT=staging git push` is the only way to scope a push or fetch to
// a login other than the active one. The env var also survives into hooks and
// subprocesses, which is what makes a whole shell session scopable without
// mutating shared state.
const EnvContextVar = "ENTIRE_CONTEXT"

// flagOverride records an explicit `--context` selection for this process. It is
// process-global for the same reason auth's insecure-HTTP opt-in is: the flag is
// parsed at the CLI edge but consumed deep inside resolution, and threading it
// through every resolver signature would touch every command that authenticates.
// One CLI invocation acts as one identity, so a process-wide value is the honest
// scope.
var flagOverride atomic.Pointer[string]

// SetFlagOverride records the `--context` value for this process. Call it once,
// during flag handling, before anything resolves a token. An empty or
// whitespace-only name clears the override rather than selecting a nameless
// context.
func SetFlagOverride(name string) {
	trimmed := strings.TrimSpace(name)
	if trimmed == "" {
		flagOverride.Store(nil)
		return
	}
	flagOverride.Store(&trimmed)
}

// SetFlagOverrideForTest sets the override for one test and restores the previous
// value when it ends.
//
// Tests using it MUST NOT call t.Parallel(): the override is process-wide, so a
// parallel test would resolve against another test's selection. That is also why
// this restores the prior value rather than clearing — nesting stays honest.
func SetFlagOverrideForTest(t interface {
	Helper()
	Cleanup(restore func())
}, name string,
) {
	t.Helper()
	prev := flagOverride.Load()
	SetFlagOverride(name)
	t.Cleanup(func() { flagOverride.Store(prev) })
}

// requestedContext returns the explicitly requested context name and the source
// to name in errors, or ("", "") when nothing was requested. The flag wins over

// 143 (not 130). We reset sig to its default disposition, re-raise it to
// ourselves, and briefly wait for delivery; if the re-raise can't be delivered
// (e.g. Windows, where signal-to-self is unsupported) we fall back to a
// conventional 128+signal exit so we never hang.
func dieFromSignal(sig os.Signal) {
	signal.Reset(sig)
	if p, err := os.FindProcess(os.Getpid()); err == nil {
		if err := p.Signal(sig); err == nil {
			time.Sleep(500 * time.Millisecond) // signal delivery ends the process well before this elapses
		}
	}
	os.Exit(exitCodeForSignal(sig))
}

// exitCodeForSignal maps a signal to the conventional 128+signum exit code
// (130 for SIGINT, 143 for SIGTERM), falling back to 130 for a signal that
// doesn't carry a numeric value on this platform.
func exitCodeForSignal(sig os.Signal) int {
	if s, ok := sig.(syscall.Signal); ok {
		return 128 + int(s)
	}
	return 130
}

// isPositionalArgError reports whether err looks like a cobra positional-
// arg validator failure. cobra's stock validators (ExactArgs, NoArgs,
// MinimumNArgs, MaximumNArgs, RangeArgs) all surface error strings
// containing "arg(s)", and that substring doesn't appear in cobra's other
// error paths or in the cli's own errors — so it's a stable, cheap
// discriminator without reaching into cobra internals.
func isPositionalArgError(err error) bool {
	return strings.Contains(err.Error(), "arg(s)")
}

func showSuggestion(cmd *cobra.Command, err error) {
	// Print usage first (brew style)
	fmt.Fprint(cmd.OutOrStderr(), cmd.UsageString())
	fmt.Fprintf(cmd.OutOrStderr(), "\nError: Invalid usage: %v\n", err)
}

	// of Command.execute() as soon as RunE errors or required-flag validation
	// fails, both before its PersistentPostRun loop, so those paths would
	// otherwise exit with up to 8KB of buffered diagnostics unwritten. The logger
	// rides the executed command's context, where the root pre-run put it; a
	// failure raised before any pre-run carries none, and nothing logged yet.
	if l := logging.LoggerFromContext(executed.Context()); l != nil {
		_ = l.Close()
	}

	if err != nil {
		var silent *cli.SilentError

		switch {
		case errors.Is(err, context.Canceled) && procsignal.Load() != nil:
			// A signal cancelled the root context (our handler fired) or a
			// keyring read was aborted by Ctrl-C. Don't dump the raw
			// transport/keyring cancellation string ("...: context canceled",
			// "read access token: signal: interrupt") as if it were a failure
			// — die quietly by re-raising the signal that triggered it (see
			// dieFromSignal) so an enclosing `while ...; do entire; done` loop
			// actually breaks on a single Ctrl-C, and a SIGTERM shutdown still
			// exits 143.
			//
			// We gate on a signal having been recorded rather than on the
			// error type alone: a context.Canceled that arose without a signal
			// (e.g. an internally-cancelled sub-context) is a genuine error
			// and must fall through to normal reporting, not masquerade as a
			// user abort (which would also wrongly break an enclosing loop).
			// procsignal is the shared source of truth written both by the
			// handler above and by the keyring interrupt path; the latter
			// records the signal on this same goroutine before returning, so
			// this Load never races that write.
			cancel()
			dieFromSignal(terminatingSignal())
		case errors.As(err, &silent):
			// Command already printed the error
		case strings.Contains(err.Error(), "unknown command") || strings.Contains(err.Error(), "unknown flag"):
			showSuggestion(rootCmd, err)
		case isPositionalArgError(err):
			// Arg-count errors come from cobra's own validators (e.g.
			// cobra.ExactArgs) and surface as "accepts N arg(s), received M".
			// Show the failing subcommand's usage so the user sees what it
			// actually expects — rootCmd's usage isn't useful for a
			// subcommand-level arg mismatch. ExecuteContextC returns the
			// deepest matched command, which is the one that failed.
			showSuggestion(executed, err)
		default:
			// The choke point for everything a command returns rather than
			// prints itself: see cli.RenderUserFacingError for what it strips
			// and which other render sites exist.
			fmt.Fprintln(rootCmd.OutOrStderr(), cli.RenderUserFacingError(err))
		}

		cancel()
		os.Exit(1)
	}
	if cli.ShouldCheckCheckpointPolicyWarning(executed) {
		cli.WarnCheckpointPolicyIfNeeded(ctx, rootCmd.ErrOrStderr(), versioninfo.Version)
	}
	cancel() // Cleanup on successful exit
}

